insert into public.chapters (name, slug, tagline, meets, venue, lead_id) values
  ('North chapter', 'north', 'The biggest chapter, and the one that never cancels for weather.', 'Every other Tuesday, 19:00', 'Upper room, North Street library', '00000000-0000-4000-8000-000000702598'),
  ('East chapter', 'east', 'Workshops first, small talk after. Bring a laptop.', 'Wednesdays, 18:30', 'East market hall, mezzanine', '00000000-0000-4000-8000-000000702633'),
  ('Old town chapter', 'old-town', 'Long tables, long evenings, and the best-kept minutes in the club.', 'First Thursday of the month, 19:30', 'The cellar, Old Town brewing society', '00000000-0000-4000-8000-000000702528'),
  ('Harbour chapter', 'harbour', 'Meets by the water and walks the quay when it does not rain.', 'Mondays, 18:00', 'Harbour light cooperative, net loft', '00000000-0000-4000-8000-000000702584'),
  ('Northwest coastal chapter', 'northwest-coastal', 'Spread along the coast road, so half its meetings happen online.', 'Thursdays, 19:00 (online every other week)', 'Coastguard station, lookout room', '00000000-0000-4000-8000-000000702507'),
  ('West chapter', 'west', 'Small on purpose: everyone knows everyone by the second visit.', 'Fridays, 18:00', 'West park pavilion', '00000000-0000-4000-8000-000000702667'),
  ('South chapter', 'south', 'Runs the club picnic every summer and will tell you about it.', 'Saturdays, 10:00', 'South community garden, greenhouse', '00000000-0000-4000-8000-000000702630'),
  ('University chapter', 'university', 'The youngest chapter, with a reading list longer than its history.', 'Tuesdays in term time, 17:30', 'Seminar room 4, the old library', '00000000-0000-4000-8000-000000702516');
